const HIMALAYAN_ALTITUDE_ZONES=[{id:"foothills",name:"Foothills & Terai-Shiwaliks",altitudeRange:"300m - 1,500m",minAltitudeMeters:300,maxAltitudeMeters:1500,geography:"Duar valleys, swampy grasslands, Sal (Shorea robusta) forests, and outer Siwalik sandstone ridges.",communities:["Tharu","Van Gujjar","Raji"],dailyLife:"Subtropical agriculture growing paddy, sugarcane, and mustard. Seasonal transhumant pastoralism where Van Gujjars move cattle up towards summer alpine pastures.",culturalNotes:"Vibrant oral folk traditions, timber craftsmanship, and sacred grove (Devbhumi) preservation customs.",keyHighlight:"The lush eco-tone connecting the Indo-Gangetic plains with the rising mountain walls.",layerTransformSpeed:.15,themeColor:"#4ade80"},{id:"mid-altitude",name:"Mid-Altitude Towns & Lesser Himalayas",altitudeRange:"1,500m - 3,000m",minAltitudeMeters:1500,maxAltitudeMeters:3e3,geography:"Dense forests of Deodar cedar, Blue Pine, and Himalayan Oak, carved by deep river gorges.",communities:["Pahari","Garhwali","Kumaoni","Himachali"],dailyLife:"Meticulous step-terrace farming (Rajma, Millets, Apples, Plums). Traditional Kath-Kuni (wood-and-stone timber-bonded) earthquake-resistant architecture.",culturalNotes:"Village deity (Palki Devta) governance, Jagara music nights, and seasonal Harvest festivals like Phool Dei and Harela.",keyHighlight:"Heartland of Himalayan mountain farming communities and ancient trade villages.",layerTransformSpeed:.3,themeColor:"#38bdf8"},{id:"high-altitude",name:"High-Altitude Villages & Greater Himalayas",altitudeRange:"3,000m - 5,000m",minAltitudeMeters:3e3,maxAltitudeMeters:5e3,geography:"High alpine meadows (Bugyals), dwarf rhododendron scrub, granite cliffs, and permanent snowline borders.",communities:["Bhotia","Kinnauri","Monpa","Sherpa"],dailyLife:"Barley and buckwheat cultivation in brief summer months; Yak breeding, wool spinning, and trans-Himalayan wool trade history.",culturalNotes:"Intricate silver jewelry, hand-woven carpet looms (Thulma & Chutka blankets), and sacred mountain pass worship (La-tse chortens).",keyHighlight:"Surviving in thin air: ancient adaptation to harsh alpine winters and high-altitude transhumance.",layerTransformSpeed:.5,themeColor:"#a855f7"},{id:"glacial-zone",name:"Glacial & Trans-Himalayan Cold Deserts",altitudeRange:"Above 5,000m",minAltitudeMeters:5e3,maxAltitudeMeters:7500,geography:"Cold high-altitude desert plateaus (Ladakh, Spiti, Zanskar), glacial ice-falls (Siachen, Gangotri), and saline lakes.",communities:["Changpa Nomads","Ladakhi","Spitian"],dailyLife:"Nomadic tent-dwelling (Rebo tents made of yak hair) on the Changthang plateau; herding high-altitude Changthangi Pashmina goats.",culturalNotes:"Mahayana & Vajrayana Buddhist monastic culture, Losar New Year celebrations, mud-brick solar architecture, and prayer flag traditions.",keyHighlight:"The extreme limit of human habitation, where culture harmonizes with ice and silence.",layerTransformSpeed:.75,themeColor:"#e2e8f0"}];function validateHimalayanData(a){if(!Array.isArray(a))return{isValid:!1,errors:["Data is not an array"]};const e=[];return a.forEach((a,t)=>{a.id||e.push(`Zone at ${t} missing id`),a.name||e.push(`Zone ${a.id||t} missing name`),"number"==typeof a.minAltitudeMeters&&"number"==typeof a.maxAltitudeMeters||e.push(`Zone ${a.id||t} missing altitude bounds`),Array.isArray(a.communities)&&0!==a.communities.length||e.push(`Zone ${a.id||t} missing communities`)}),{isValid:0===e.length,errors:e}}function calculateAltitudeFromScroll(a,e=300,t=6500){const n=Math.max(0,Math.min(100,a));return Math.round(e+n/100*(t-e))}function getZoneForAltitude(a,e=HIMALAYAN_ALTITUDE_ZONES){return a<=1500?e[0]:a<=3e3?e[1]:a<=5e3?e[2]:e[3]}function calculateParallaxTranslateY(a,e){const t=Math.max(0,Math.min(100,a));return Math.round(t*e*2.5*100)/100}function initHimalayanScrollytelling(){const a=document.getElementById("altitude-val"),e=document.getElementById("active-zone-title"),t=document.getElementById("active-zone-range"),n=document.getElementById("para-layer-1"),i=document.getElementById("para-layer-2"),r=document.getElementById("para-layer-3");function l(){const l=document.body.scrollHeight-window.innerHeight;if(l<=0)return;const o=window.scrollY/l*100,s=calculateAltitudeFromScroll(o),d=getZoneForAltitude(s);if(a&&(a.textContent=s.toLocaleString()+" m"),e&&(e.textContent=d.name),t&&(t.textContent=d.altitudeRange),n){const a=calculateParallaxTranslateY(o,.15);n.style.transform=`translateY(${a}px)`}if(i){const a=calculateParallaxTranslateY(o,.35);i.style.transform=`translateY(${a}px)`}if(r){const a=calculateParallaxTranslateY(o,.6);r.style.transform=`translateY(${a}px)`}}window.addEventListener("scroll",l,{passive:!0}),l()}"undefined"!=typeof window&&"undefined"!=typeof document&&document.addEventListener("DOMContentLoaded",initHimalayanScrollytelling);export{HIMALAYAN_ALTITUDE_ZONES,validateHimalayanData,calculateAltitudeFromScroll,getZoneForAltitude,calculateParallaxTranslateY};